/*
 * shadcn/typeset
 * https://ui.shadcn.com/docs/typeset.
 */

/* One flow unit for all vertical rhythm. Registered as a length, so the 1.5em
   set on .typeset resolves there, against the body size, and descendants
   inherit pixels: a code block (14px), an h3 (18px), and a paragraph all space
   from the same 24px instead of 1.5em of their own size. */
@property --typeset-flow {
  inherits: true;
  initial-value: 24px;
  syntax: "<length>";
}

@layer components {
  .typeset {
    color: var(--color-foreground, currentColor);
    font-family: var(--font-sans);
    font-size: var(--text-body);
    line-height: var(--text-body--line-height);
    margin-trim: block-start;
    overflow-wrap: break-word;

    --typeset-flow: 1.5em;
    --typeset-muted: var(
      --color-muted-foreground,
      color-mix(in oklab, currentColor 60%, transparent)
    );
    --typeset-rule: var(--color-border, color-mix(in oklab, currentColor 20%, transparent));
  }

  .typeset *:not(:where(.not-typeset, [data-not-typeset], .not-typeset *, [data-not-typeset] *)) {
    /* Paragraphs. */
    &:where(p) {
      margin-block: var(--typeset-flow) 0;
      text-wrap: pretty;
    }

    /* Headings. */
    &:where(h1, h2, h3, h4, h5, h6) {
      color: var(--color-foreground, currentColor);
      font-family: var(--font-heading);
      font-weight: 600;
      margin-block-end: 0;
      text-wrap: balance;
    }

    &:where(h1) {
      font-size: var(--text-display);
      font-weight: var(--text-display--font-weight);
      line-height: var(--text-display--line-height);
      margin-block-start: calc(var(--typeset-flow) * 2);
    }

    &:where(h2) {
      font-size: var(--text-title);
      font-weight: var(--text-title--font-weight);
      line-height: var(--text-title--line-height);
      margin-block-start: calc(var(--typeset-flow) * 2);
    }

    &:where(h3) {
      font-size: var(--text-subtitle);
      font-weight: var(--text-subtitle--font-weight);
      line-height: var(--text-subtitle--line-height);
      margin-block-start: calc(var(--typeset-flow) * 1.25);
    }

    &:where(h4, h5, h6) {
      font-size: 1em;
      line-height: var(--text-body--line-height);
      margin-block-start: calc(var(--typeset-flow) * 1.25);
    }

    /* Anchors. */
    &:where([id]) {
      scroll-margin-block-start: var(--typeset-flow);
    }

    /* Headings own the space below them: less than above, so a heading
       groups with what it introduces. */
    &:where(h1 + *, h2 + *, h3 + *, h4 + *, h5 + *, h6 + *) {
      margin-block-start: calc(var(--typeset-flow) * 2 / 3);
    }

    /* Links. */
    &:where(a) {
      color: inherit;
      font-weight: 500;
      text-decoration-color: color-mix(in oklab, currentcolor 30%, transparent);
      text-decoration-line: underline;
      text-decoration-thickness: from-font;
      text-underline-offset: 0.2em;
      text-underline-position: from-font;
    }

    &:where(a:hover) {
      text-decoration-color: currentcolor;
    }

    &:where(a:focus-visible) {
      border-radius: 0.125em;
      outline: 2px solid var(--color-ring, currentColor);
      outline-offset: 2px;
    }

    &:where(:is(h1, h2, h3, h4, h5, h6) :is(a)) {
      font-weight: inherit;
    }

    /* Inline semantics. */
    &:where(strong, b) {
      font-weight: 600;
    }

    &:where(:is(h1, h2, h3, h4) :is(strong, b)) {
      font-weight: 600;
    }

    &:where(mark) {
      padding: 0.05em 0.15em;
      border-radius: 0.2em;
      background-color: var(
        --color-warning-soft,
        color-mix(in oklab, currentColor 12%, transparent)
      );
      color: inherit;
    }

    &:where(abbr[title]) {
      cursor: help;
      text-decoration-line: underline;
      text-decoration-style: dotted;
      text-underline-offset: 0.2em;
    }

    &:where(del, s) {
      color: var(--typeset-muted);
      text-decoration-line: line-through;
    }

    &:where(sup, sub) {
      position: relative;
      font-size: 0.75em;
      line-height: 0;
      vertical-align: baseline;
    }

    &:where(sup) {
      top: -0.5em;
    }

    &:where(sub) {
      bottom: -0.25em;
    }

    &:where(sup a) {
      font-weight: 500;
      text-decoration-line: none;
    }

    /* Lists. */
    &:where(ul) {
      list-style-type: disc;
    }

    &:where(ol) {
      list-style-type: decimal;
    }

    &:where(ul ul) {
      list-style-type: circle;
    }

    &:where(ul ul ul) {
      list-style-type: square;
    }

    &:where(ol[type="a" i]) {
      list-style-type: lower-alpha;
    }

    &:where(ol[type="i" i]) {
      list-style-type: lower-roman;
    }

    &:where(ol[type="A" s]) {
      list-style-type: upper-alpha;
    }

    &:where(ol[type="I" s]) {
      list-style-type: upper-roman;
    }

    &:where(ul, ol) {
      margin-block: var(--typeset-flow) 0;
      padding-inline-start: 1.5em;
    }

    &:where(li) {
      margin-block-start: calc(var(--typeset-flow) / 3);
      padding-inline-start: 0.375em;
    }

    &:where(li > p, li > ul, li > ol) {
      margin-block-start: calc(var(--typeset-flow) / 3);
    }

    &:where(ul > li)::marker {
      color: var(--typeset-muted);
    }

    &:where(ol > li)::marker {
      color: var(--typeset-muted);
    }

    /* GFM task lists. */
    &:where(ul.contains-task-list) {
      list-style-type: none;
      padding-inline-start: 0.25em;
    }

    &:where(li.task-list-item > input[type="checkbox"]) {
      accent-color: var(--color-selection, currentColor);
      margin-inline-end: 0.5em;
      vertical-align: -0.1em;
    }

    /* Disclosures. */
    &:where(details) {
      margin-block: var(--typeset-flow) 0;
    }

    &:where(summary) {
      cursor: pointer;
      font-weight: 500;
    }

    &:where(summary)::marker {
      color: var(--typeset-muted);
    }

    /* Keyboard keys. */
    &:where(kbd) {
      padding: 0.0625em 0.35em;
      border: 1px solid var(--typeset-rule);
      border-radius: min(calc(var(--radius, 0.5em) * 0.6), 0.35em);
      border-block-end-width: 2px;
      font-family: inherit;
      font-size: 0.875em;
      font-size: round(nearest, 0.875em, 1px);
      font-weight: 500;
    }

    /* Definition lists. */
    &:where(dl) {
      margin-block: var(--typeset-flow) 0;
    }

    &:where(dt) {
      font-weight: 500;
      margin-block-start: calc(var(--typeset-flow) * 2 / 3);
    }

    &:where(dt + dt) {
      margin-block-start: calc(var(--typeset-flow) / 6);
    }

    &:where(dd) {
      color: var(--typeset-muted);
      margin-block-start: calc(var(--typeset-flow) / 6);
      margin-inline-start: 0;
      padding-inline-start: 1em;
    }

    /* Inline code. */
    &:where(:not(pre) > code) {
      padding: 0.125em 0.3em;
      border-radius: min(calc(var(--radius, 0.5em) * 0.6), 0.35em);
      background-color: var(--color-muted, color-mix(in oklab, currentColor 8%, transparent));

      @apply text-inline-code;
    }

    /* Code blocks. */
    &:where(pre) {
      padding: 0.75em 1em;
      border-radius: var(--radius, 0.5em);
      background-color: var(--color-muted, color-mix(in oklab, currentColor 8%, transparent));
      direction: ltr;
      font-family: var(--font-mono);
      margin-block: var(--typeset-flow) 0;
      overflow-x: auto;
      tab-size: 2;

      @apply text-code-block;
    }

    &:where(pre code) {
      padding: 0;
      border-radius: 0;
      background-color: transparent;
      font-family: inherit;
      font-size: inherit;
    }

    /* Blockquote. */
    &:where(blockquote) {
      border-inline-start: 2px solid var(--typeset-rule);
      margin-block: var(--typeset-flow) 0;
      margin-inline: 0;
      padding-inline-start: 1em;
    }

    /* Dividers. The same space on both sides, so the rule sits centered
       between the sections it separates. */
    &:where(hr) {
      border: 0;
      border-block-start: 1px solid var(--typeset-rule);
      margin-block: calc(var(--typeset-flow) * 2) 0;
    }

    &:where(hr + *) {
      margin-block-start: calc(var(--typeset-flow) * 2);
    }

    /* GFM footnotes. */
    &:where(.footnotes, [data-footnotes]) {
      border-block-start: 1px solid var(--typeset-rule);
      color: var(--typeset-muted);
      font-size: 0.875em;
      margin-block-start: calc(var(--typeset-flow) * 2);
      padding-block-start: var(--typeset-flow);
    }

    /* Math. */
    &:where(math[display="block"]) {
      overflow: auto hidden;
      margin-block: var(--typeset-flow) 0;
      padding-block: 0.25em;
    }

    /* Media. */
    &:where(img, video) {
      max-width: 100%;
      height: auto;
      border-radius: var(--radius, 0.5em);
      margin-block: var(--typeset-flow) 0;
    }

    &:where(p img) {
      margin-block-start: 0;
    }

    &:where(figure) {
      margin-block: var(--typeset-flow) 0;
      margin-inline: 0;
    }

    &:where(figcaption, caption) {
      color: var(--typeset-muted);
      font-size: 0.875em;
      margin-block-start: calc(var(--typeset-flow) / 2);
      text-align: center;
    }

    &:where(caption) {
      caption-side: bottom;
    }

    /* Tables. Separators sit on cells, not tr:last-child: append-safe.
       Bare tables stay real tables (keep their semantics) and wrap to fit. */
    &:where(table) {
      max-width: 100%;
      border-block-end: 1px solid var(--typeset-rule);
      border-collapse: separate;
      border-spacing: 0;
      font-size: 1em;
      font-variant-numeric: tabular-nums;
      line-height: 1.5;
      margin-block: var(--typeset-flow) 0;
    }

    /* Horizontal scroll for any wide block. Wrap it and the wrapper owns the
       flow margin. Tables shrink to fit, so widen the table to make it scroll
       instead of compress. */
    &:where(.typeset-scroll) {
      margin-block-start: var(--typeset-flow);
      overflow-x: auto;
    }

    &:where(.typeset-scroll > *) {
      margin-block-start: 0;
    }

    &:where(.typeset-scroll table) {
      width: max-content;
      max-width: none;
    }

    &:where(thead th) {
      padding: 0.625em 1em;
      font-weight: 500;
      text-align: start;
      white-space: nowrap;
    }

    &:where(:is(tbody, tfoot) :is(td, th)) {
      padding: 0.75em 1em;
      border-block-start: 1px solid var(--typeset-rule);
      text-align: start;
      vertical-align: top;
    }

    &:where(tbody th, tfoot th) {
      font-weight: 500;
    }

    &:where(th:first-child, td:first-child) {
      padding-inline-start: 0;
    }

    &:where(th[align="center"], td[align="center"]) {
      text-align: center;
    }

    &:where(th[align="right"], td[align="right"]) {
      text-align: end;
    }

    /* Blocks inside list items keep the list's tighter rhythm. */
    &:where(li > blockquote, li > table, li > figure, li > pre) {
      margin-block-start: calc(var(--typeset-flow) / 3);
    }

    @media print {
      &:where(pre, table, blockquote, figure) {
        break-inside: avoid;
      }

      &:where(h1, h2, h3, h4) {
        break-after: avoid;
      }
    }

    /* Forced colors strips the code background, so give it a border. */
    @media (forced-colors: active) {
      &:where(:not(pre) > code) {
        border: 1px solid;
      }
    }
  }

  /* A busy region (a reply still streaming in) wraps plainly: pretty and
     balanced wrapping re-flow earlier lines as each word arrives. Set
     aria-busy="true" while content streams and remove it when done. */
  .typeset:where([aria-busy="true"]) :where(p, h1, h2, h3, h4, h5, h6) {
    text-wrap: wrap;
  }

  /* First child adds no space above. Last so it wins ties. */
  .typeset
    > :where(:first-child):not(
      :where(.not-typeset, [data-not-typeset], .not-typeset *, [data-not-typeset] *)
    ),
  .typeset
    > :where(:first-child)
    > :where(:first-child):not(
      :where(.not-typeset, [data-not-typeset], .not-typeset *, [data-not-typeset] *)
    ),
  .typeset
    :where(
      li > :first-child,
      blockquote > :first-child,
      td > :first-child,
      th > :first-child,
      dd > :first-child,
      figure > :first-child,
      figure > picture > img
    ):not(:where(.not-typeset, [data-not-typeset], .not-typeset *, [data-not-typeset] *)) {
    margin-block-start: 0;
  }
}

/* Shared roles for interfaces and reading content. Sizes respect browser zoom.
   Each line height is written as line box / font size in px at a 16px root, so
   every role lands on a whole pixel and rows, borders, and baselines stay on
   the pixel grid.

   Labels are not trimmed with text-box. Cal Sans's cap height sits 0.46px
   above the centre of its line box at 14px (hhea 1800/-490, cap 1440 on a
   2000 upem), below what a pixel can show. Trimming to the cap height would
   also centre Arabic text on Vazirmatn's cap metric, which Arabic letterforms
   do not use, and shift it about 2px. */
@theme static {
  --text-display: 2rem;
  --text-display--line-height: calc(40 / 32);
  --text-display--font-weight: 700;
  --text-title: 1.5rem;
  --text-title--line-height: calc(32 / 24);
  --text-title--font-weight: 600;
  --text-subtitle: 1.125rem;
  --text-subtitle--line-height: calc(26 / 18);
  --text-subtitle--font-weight: 600;
  --text-body: 1rem;
  --text-body--line-height: calc(26 / 16);
  --text-body--font-weight: 400;
  --text-caption: 0.875rem;
  --text-caption--line-height: calc(22 / 14);
  --text-caption--font-weight: 400;

  /* Density roles: controls and supporting text are not article paragraphs. */
  --text-control: 0.875rem;
  --text-control--line-height: calc(20 / 14);
  --text-control--font-weight: 500;
  --text-control-sm: 0.75rem;
  --text-control-sm--line-height: calc(18 / 12);
  --text-control-sm--font-weight: 500;
}

@utility text-display {
  font-family: var(--font-heading);
  text-wrap: balance;
}

@utility text-title {
  font-family: var(--font-heading);
  text-wrap: balance;
}

@utility text-subtitle {
  font-family: var(--font-heading);
  text-wrap: balance;
}

/* Selected labels. Going from a control role's 500 to 600 widens a label by up
   to 6.3px at 14px, which pushes its neighbors or moves its ellipsis. Cal Sans
   narrows as its optical size rises, so each control role pairs 600 with a
   raised opsz, measured to hold 5–30 character labels within 1px of their
   500 width: 18.5 at 14px, 17 at 12px. Vazirmatn has no opsz axis and ignores
   the setting. Use font-selected inside a control role; outside one it is a
   plain 600. */
@layer base {
  :root {
    --text-control--selected-variation: "opsz" 18.5;
    --text-control-sm--selected-variation: "opsz" 17;
  }
}

@utility text-control {
  --selected-variation: var(--text-control--selected-variation);
}

@utility text-control-sm {
  --selected-variation: var(--text-control-sm--selected-variation);
}

@utility font-selected {
  --tw-font-weight: 600;

  font-variation-settings: var(--selected-variation, normal);
  font-weight: 600;
}

/* Body and caption carry no wrap style: an element that takes the role passes
   it to every descendant, so a message, label, or streamed reply would re-wrap
   lines already on screen. Paragraphs get pretty wrapping in base.css. */

/* Arabic-script marks need more vertical room. Keep natural tracking. */
@layer base {
  :where(:lang(ar), :lang(fa), :lang(ur)) {
    --text-display--line-height: calc(48 / 32);
    --text-title--line-height: calc(36 / 24);
    --text-subtitle--line-height: calc(28 / 18);
    --text-body--line-height: calc(28 / 16);
    --text-caption--line-height: calc(24 / 14);
    --text-control--line-height: calc(22 / 14);
    --text-control-sm--line-height: calc(20 / 12);
    --text-field--line-height: calc(28 / 16);
  }
}

@layer base {
  :where(code, pre) {
    font-variant-ligatures: none;
  }
}

/* Supporting roles reuse the scale; they do not expose another size ladder. */
@utility text-metadata {
  font-size: var(--text-control-sm);
  font-weight: 400;
  line-height: var(--text-control-sm--line-height);
}

/* One code size and leading for every surface that shows source: code blocks
   and the Pierre-backed file and diff views, which read these in their shadow roots.
   22px leading at 14px, the caption's line box, kept whole so line numbers and
   diff rows don't drift off the pixel grid. Not tied to the caption token: code
   stays left-to-right and does not take the Arabic-script leading. */
@layer base {
  :root {
    --code-font-size: var(--text-caption);
    --code-line-height: calc(22 / 14);
  }
}

@utility text-code-block {
  font-family: var(--font-mono);
  font-size: var(--code-font-size);
  font-variant-ligatures: none;
  font-weight: 400;
  line-height: var(--code-line-height);
}

/* Rounded to a whole pixel: 0.875em of a 14px caption would be 12.25px. */
@utility text-inline-code {
  font-family: var(--font-mono);
  font-size: 0.875em;
  font-size: round(nearest, 0.875em, 1px);
  font-variant-ligatures: none;
  font-weight: 400;
  line-height: inherit;
  overflow-wrap: anywhere;
}

/* Editable text follows its preview rather than establishing another scale. */
@utility text-editable {
  font: inherit;
  letter-spacing: inherit;
}

/* Touch inputs stay at 16px, even on tablets with a wide viewport. The 1.5rem
   leading fills a 2rem control exactly (1.5rem + 0.375rem padding + border),
   so single-line fields match buttons and selects at the mobile height. */
@utility text-field {
  font-size: var(--text-body);
  font-weight: 400;
  line-height: var(--text-field--line-height, 1.5rem);

  @media (width >= 48rem) and (pointer: fine) {
    font-size: var(--text-control);
    line-height: var(--text-control--line-height);
  }
}

/*
 * Erbium-only variants and tokens. The shared data-* state variants, accordion
 * keyframes, scroll-fade, shimmer and no-scrollbar utilities come from
 * `shadcn/tailwind.css`, imported in globals.css.
 */

@theme inline {
  --animate-accordion-down: accordion-down 0.2s ease-out;
  --animate-accordion-up: accordion-up 0.2s ease-out;
}

/* Persistent control engagement, independent of the primitive's state API. */
@custom-variant engaged {
  &:where(
    [aria-expanded="true"],
    [aria-pressed="true"],
    [data-state="on"],
    [data-popup-open]:not([data-popup-open="false"])
  ) {
    @slot;
  }
}

/*
 * A Field or FieldItem row that pairs a choice control (`[data-choice]`:
 * checkbox, radio, switch) with a direct `FieldLabel` or `FieldContent`. Such a
 * row top-aligns and centres the control on the label's first line through
 * `choice-first-line`. Rows that only borrow Field's layout, such as an `Item`
 * rendered as a Field with its label nested deeper, keep their own alignment.
 */
@custom-variant choice-row {
  &:has(> [data-choice]):has(> [data-slot="field-label"], > [data-slot="field-content"]) {
    @slot;
  }
}
